/**
 * @file 04_lru_seq.v
 * @brief Address ROM for the fully associative exam, including four LRU victim walks.
 */

/**
 * @brief Address ROM for the fully associative exam, including four LRU victim walks.
 *
 * Tests 0 to 7 are the analyzer suite. The four walks that follow show which line LRU replaces. phase is the test number during the suite and restarts for the victim index. The cache is cleared between tests.
 *
 * Address list generated by gen_board_seq.py. The suite repeats. The cache is cleared between tests. phase is the test number. Tests 0-7 are the analyzer suite. The four that follow are LRU victims (phase restarts at 0 and counts the victim index).
 */

module lru_seq (
    input wire clk, ///< Clock.
    input wire ce, ///< Clock enable. The state machine advances only when this is high.
    input wire rst, ///< Synchronous reset.
    input wire cache_idle, ///< High when the cache is idle and can take a new address.
    input wire done, ///< High when this access has produced data_out.
    output reg [7:0] address, ///< Byte address in the 256-byte memory.
    output reg req, ///< Access request. Accepted while the controller is idle.
    output reg clear_cache, ///< Holds the cache in reset between tests.
    output reg [2:0] phase ///< Test number. The cache is cleared between tests.
);
    localparam ISSUE = 2'd0, DROP = 2'd1, WAIT = 2'd2, GAP = 2'd3;

    reg [1:0] st;
    reg [6:0] n;
    reg [2:0] gap;

    localparam LAST = 7'd90;

    function [7:0] rom;
        input [6:0] i;
        begin
            case (i)
                7'd0  : rom = 8'h00;
                7'd1  : rom = 8'h00;
                7'd2  : rom = 8'h00;
                7'd3  : rom = 8'h00;
                7'd4  : rom = 8'h00;
                7'd5  : rom = 8'h00;
                7'd6  : rom = 8'h01;
                7'd7  : rom = 8'h02;
                7'd8  : rom = 8'h03;
                7'd9  : rom = 8'h04;
                7'd10 : rom = 8'h05;
                7'd11 : rom = 8'h06;
                7'd12 : rom = 8'h07;
                7'd13 : rom = 8'h00;
                7'd14 : rom = 8'h10;
                7'd15 : rom = 8'h00;
                7'd16 : rom = 8'h10;
                7'd17 : rom = 8'h00;
                7'd18 : rom = 8'h04;
                7'd19 : rom = 8'h08;
                7'd20 : rom = 8'h0C;
                7'd21 : rom = 8'h00;
                7'd22 : rom = 8'h04;
                7'd23 : rom = 8'h08;
                7'd24 : rom = 8'h0C;
                7'd25 : rom = 8'h00;
                7'd26 : rom = 8'h00;
                7'd27 : rom = 8'h10;
                7'd28 : rom = 8'h00;
                7'd29 : rom = 8'h00;
                7'd30 : rom = 8'h04;
                7'd31 : rom = 8'h00;
                7'd32 : rom = 8'h04;
                7'd33 : rom = 8'h03;
                7'd34 : rom = 8'h02;
                7'd35 : rom = 8'h01;
                7'd36 : rom = 8'h00;
                7'd37 : rom = 8'hFC;
                7'd38 : rom = 8'hFF;
                7'd39 : rom = 8'h00;
                7'd40 : rom = 8'h04;
                7'd41 : rom = 8'h08;
                7'd42 : rom = 8'h0C;
                7'd43 : rom = 8'h04;
                7'd44 : rom = 8'h08;
                7'd45 : rom = 8'h0C;
                7'd46 : rom = 8'h10;
                7'd47 : rom = 8'h04;
                7'd48 : rom = 8'h08;
                7'd49 : rom = 8'h0C;
                7'd50 : rom = 8'h10;
                7'd51 : rom = 8'h00;
                7'd52 : rom = 8'h00;
                7'd53 : rom = 8'h04;
                7'd54 : rom = 8'h08;
                7'd55 : rom = 8'h0C;
                7'd56 : rom = 8'h00;
                7'd57 : rom = 8'h08;
                7'd58 : rom = 8'h0C;
                7'd59 : rom = 8'h10;
                7'd60 : rom = 8'h00;
                7'd61 : rom = 8'h08;
                7'd62 : rom = 8'h0C;
                7'd63 : rom = 8'h10;
                7'd64 : rom = 8'h04;
                7'd65 : rom = 8'h00;
                7'd66 : rom = 8'h04;
                7'd67 : rom = 8'h08;
                7'd68 : rom = 8'h0C;
                7'd69 : rom = 8'h00;
                7'd70 : rom = 8'h04;
                7'd71 : rom = 8'h0C;
                7'd72 : rom = 8'h10;
                7'd73 : rom = 8'h00;
                7'd74 : rom = 8'h04;
                7'd75 : rom = 8'h0C;
                7'd76 : rom = 8'h10;
                7'd77 : rom = 8'h08;
                7'd78 : rom = 8'h00;
                7'd79 : rom = 8'h04;
                7'd80 : rom = 8'h08;
                7'd81 : rom = 8'h0C;
                7'd82 : rom = 8'h00;
                7'd83 : rom = 8'h04;
                7'd84 : rom = 8'h08;
                7'd85 : rom = 8'h10;
                7'd86 : rom = 8'h00;
                7'd87 : rom = 8'h04;
                7'd88 : rom = 8'h08;
                7'd89 : rom = 8'h10;
                7'd90 : rom = 8'h0C;
                default: rom = 8'h00;
            endcase
        end
    endfunction

    function is_end;
        input [6:0] i;
        begin
            is_end = i == 7'd4 || i == 7'd12 || i == 7'd16 || i == 7'd24 || i == 7'd28 || i == 7'd32 || i == 7'd36 || i == 7'd38 || i == 7'd51 || i == 7'd64 || i == 7'd77 || i == 7'd90;
        end
    endfunction

    function [2:0] phase_of;
        input [6:0] i;
        begin
            case (i)
            7'd0  : phase_of = 3'd0;
            7'd1  : phase_of = 3'd0;
            7'd2  : phase_of = 3'd0;
            7'd3  : phase_of = 3'd0;
            7'd4  : phase_of = 3'd0;
            7'd5  : phase_of = 3'd1;
            7'd6  : phase_of = 3'd1;
            7'd7  : phase_of = 3'd1;
            7'd8  : phase_of = 3'd1;
            7'd9  : phase_of = 3'd1;
            7'd10 : phase_of = 3'd1;
            7'd11 : phase_of = 3'd1;
            7'd12 : phase_of = 3'd1;
            7'd13 : phase_of = 3'd2;
            7'd14 : phase_of = 3'd2;
            7'd15 : phase_of = 3'd2;
            7'd16 : phase_of = 3'd2;
            7'd17 : phase_of = 3'd3;
            7'd18 : phase_of = 3'd3;
            7'd19 : phase_of = 3'd3;
            7'd20 : phase_of = 3'd3;
            7'd21 : phase_of = 3'd3;
            7'd22 : phase_of = 3'd3;
            7'd23 : phase_of = 3'd3;
            7'd24 : phase_of = 3'd3;
            7'd25 : phase_of = 3'd4;
            7'd26 : phase_of = 3'd4;
            7'd27 : phase_of = 3'd4;
            7'd28 : phase_of = 3'd4;
            7'd29 : phase_of = 3'd5;
            7'd30 : phase_of = 3'd5;
            7'd31 : phase_of = 3'd5;
            7'd32 : phase_of = 3'd5;
            7'd33 : phase_of = 3'd6;
            7'd34 : phase_of = 3'd6;
            7'd35 : phase_of = 3'd6;
            7'd36 : phase_of = 3'd6;
            7'd37 : phase_of = 3'd7;
            7'd38 : phase_of = 3'd7;
            7'd39 : phase_of = 3'd0;
            7'd40 : phase_of = 3'd0;
            7'd41 : phase_of = 3'd0;
            7'd42 : phase_of = 3'd0;
            7'd43 : phase_of = 3'd0;
            7'd44 : phase_of = 3'd0;
            7'd45 : phase_of = 3'd0;
            7'd46 : phase_of = 3'd0;
            7'd47 : phase_of = 3'd0;
            7'd48 : phase_of = 3'd0;
            7'd49 : phase_of = 3'd0;
            7'd50 : phase_of = 3'd0;
            7'd51 : phase_of = 3'd0;
            7'd52 : phase_of = 3'd1;
            7'd53 : phase_of = 3'd1;
            7'd54 : phase_of = 3'd1;
            7'd55 : phase_of = 3'd1;
            7'd56 : phase_of = 3'd1;
            7'd57 : phase_of = 3'd1;
            7'd58 : phase_of = 3'd1;
            7'd59 : phase_of = 3'd1;
            7'd60 : phase_of = 3'd1;
            7'd61 : phase_of = 3'd1;
            7'd62 : phase_of = 3'd1;
            7'd63 : phase_of = 3'd1;
            7'd64 : phase_of = 3'd1;
            7'd65 : phase_of = 3'd2;
            7'd66 : phase_of = 3'd2;
            7'd67 : phase_of = 3'd2;
            7'd68 : phase_of = 3'd2;
            7'd69 : phase_of = 3'd2;
            7'd70 : phase_of = 3'd2;
            7'd71 : phase_of = 3'd2;
            7'd72 : phase_of = 3'd2;
            7'd73 : phase_of = 3'd2;
            7'd74 : phase_of = 3'd2;
            7'd75 : phase_of = 3'd2;
            7'd76 : phase_of = 3'd2;
            7'd77 : phase_of = 3'd2;
            7'd78 : phase_of = 3'd3;
            7'd79 : phase_of = 3'd3;
            7'd80 : phase_of = 3'd3;
            7'd81 : phase_of = 3'd3;
            7'd82 : phase_of = 3'd3;
            7'd83 : phase_of = 3'd3;
            7'd84 : phase_of = 3'd3;
            7'd85 : phase_of = 3'd3;
            7'd86 : phase_of = 3'd3;
            7'd87 : phase_of = 3'd3;
            7'd88 : phase_of = 3'd3;
            7'd89 : phase_of = 3'd3;
            7'd90 : phase_of = 3'd3;
                default: phase_of = 3'd0;
            endcase
        end
    endfunction

    /**
     * @brief Issue the next address while the cache is idle, then clear the cache after the last address of a test.
     */
    always @(posedge clk) begin
        if (rst) begin
            st <= ISSUE;
            n <= 7'd0;
            gap <= 3'd0;
            address <= 8'h00;
            req <= 1'b0;
            clear_cache <= 1'b0;
            phase <= 3'd0;
        end else if (ce) begin
            req <= 1'b0;
            case (st)
                ISSUE: begin
                    clear_cache <= 1'b0;
                    phase <= phase_of(n);
                    if (cache_idle && !done) begin
                        address <= rom(n);
                        req <= 1'b1;
                        st <= DROP;
                    end
                end
                DROP: st <= WAIT;
                WAIT: begin
                    if (done) begin
                        if (is_end(n)) begin
                            n <= (n == LAST) ? 7'd0 : n + 7'd1;
                            clear_cache <= 1'b1;
                            gap <= 3'd0;
                            st <= GAP;
                        end else begin
                            n <= n + 7'd1;
                            st <= ISSUE;
                        end
                    end
                end
                GAP: begin
                    clear_cache <= 1'b1;
                    phase <= phase_of(n);
                    if (gap == 3'd4) begin
                        clear_cache <= 1'b0;
                        st <= ISSUE;
                    end else begin
                        gap <= gap + 3'd1;
                    end
                end
                default: st <= ISSUE;
            endcase
        end
    end
endmodule
